/* The login URL is generated by Keycloak for the current authentication flow.
   Its callback identifies the app, including follow-up login/reset/signup pages. */
(function () {
  /**
   * Updates the logo to the app's home page using the callback in Keycloak's
   * login URL, resolving either redirect_uri or encoded client_data.
   * Keeps the template's client home URL or EduHub fallback when callback
   * data is absent, malformed, or uses a non-HTTP(S) protocol.
   *
   * @returns {void}
   */
  function setHomeLink() {
    var link = document.getElementById('kc-home-link');
    if (!link) return;

    try {
      var params = new URL(link.dataset.loginUrl, window.location.origin).searchParams;
      var redirect = params.get('redirect_uri');
      if (!redirect && params.has('client_data')) {
        var encoded = params.get('client_data').replace(/-/g, '+').replace(/_/g, '/');
        redirect = JSON.parse(atob(encoded)).ru;
      }
      if (!redirect) return;

      var callback = new URL(redirect);
      if (callback.protocol === 'https:' || callback.protocol === 'http:') {
        link.href = callback.origin + '/';
      }
    } catch (e) {
      /* Keep the client home URL (or EduHub fallback) if no callback is available. */
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setHomeLink);
  } else {
    setHomeLink();
  }
})();
